/* config.h - HobbyOS port configuration for GNU make 4.4.1.
 *
 * Upstream, this file is generated by configure from src/config.h.in (plus
 * src/mkconfig.h for the PACKAGE_* identity).  The port keeps GNU make's
 * sources byte-identical and pins the configuration here, the same way
 * src/user/sed/config.h does for GNU sed (see docs/gnu-ports.md).
 *
 * Port policy (v1, matches docs/selfhost/buildtools-audit.md S3):
 *   - Minimal serial build: MAKE_JOBSERVER is OFF, so -j1 is the supported
 *     mode.  The jobserver machinery (jobserver_setup/acquire, the SIGCHLD
 *     interrupt of a blocking read, alarm() load-throttle) compiles out of
 *     posixos.c and job.c entirely, exactly as the audit recommends
 *     ("minimal -j1 v1").  Re-enabling -j is documented in the audit S3.3.
 *   - MAKE_LOAD is 0: the `load` directive (dlopen of shared makefiles) is
 *     not relevant on this OS (no dlfcn in the sysroot).
 *   - ENABLE_NLS 0: src/gettext.h maps _() to plain strings; no libintl.
 *   - HAVE_STRNDUP / HAVE_MEMPCPY / HAVE_WAIT3 / HAVE_SIGSETMASK are left
 *     UNDEFINED (not 0): make guards those with #ifdef/#defined(), so a
 *     value of 0 would still select the real libc call.  Same for the
 *     rlimit/pselect/ttyname/getpw*_r/struct-dirent macros.
 *   - HAVE_STRSIGNAL 0 / HAVE_STPCPY 0 / HAVE_DECL_GETLOADAVG 0 /
 *     HAVE_SYS_LOADAVG_H 0 are value-guarded (#if !X / #if X == 0), so 0
 *     correctly selects make's own fallbacks (signame.c, misc.c, job.c).
 *   - HAVE_GETLOGIN is not a configure macro in make: read.c:3114 calls
 *     getlogin() unconditionally (all non-Amiga/non-Windows builds), so the
 *     port provides a stub in hb_stubs.c (sysroot has no getlogin).
 *     Similarly getloadavg() (job.c:2138) and umask() (posixos.c os_anontmp)
 *     and alarm() are provided there; see hb_stubs.c.
 *   - vfork is not in the sysroot: defined as fork (make's own practice on
 *     vfork-less systems; job.c child_execute_job uses vfork() when
 *     USE_POSIX_SPAWN is off, which is our path).
 *   - Nothing here calls for sysroot dirent: opendir/readdir/closedir are
 *     ENOSYS in the sysroot today (parent single-writer libc milestone).
 *     Consequence (audit S3.2): make's dir cache sees no files, so VPATH,
 *     $(wildcard), implicit %-rules and default-makefile search are
 *     unavailable; explicit `make -f FILE TARGET` builds work because they
 *     resolve via stat.  make degrades gracefully: find_directory marks the
 *     directory unreadable (dc->dirfiles NULL) instead of aborting.
 *     This is the v1 contract and feeds Makefile.hobbyos.
 */

/* Configure identity (src/mkconfig.h equivalent). */
#define PACKAGE "make"
#define PACKAGE_BUGREPORT "bug-make@gnu.org"
#define PACKAGE_NAME "GNU Make"
#define PACKAGE_STRING "GNU Make 4.4.1"
#define PACKAGE_TARNAME "make"
#define PACKAGE_URL "https://www.gnu.org/software/make/"
#define PACKAGE_VERSION "4.4.1"
/* makeint.h only defaults LOCALEDIR under WINDOWS32; POSIX builds get it
 * from configure, so pin the no-NLS value here.  bindtextdomain() is a
 * no-op macro when ENABLE_NLS is 0 (gettext.h). */
#define LOCALEDIR NULL

/* mkcustom.h is the upstream customization hook (included at the end of
 * the configure-generated config.h).  It resolves alloca(), declares the
 * misc.c fallbacks (stpcpy/mempcpy/strcasecmp) and sets _GNU_SOURCE. */
#define HAVE_ALLOCA_H 1
#include "mkcustom.h"

/* Standard headers present in the sysroot. */
#define HAVE_FCNTL_H 1
#define HAVE_LIMITS_H 1
#define HAVE_STDINT_H 1
#define HAVE_STDLIB_H 1
#define HAVE_STRING_H 1
#define HAVE_STRINGS_H 1
#define HAVE_SYS_STAT_H 1
#define HAVE_SYS_TIME_H 1
#define HAVE_SYS_TYPES_H 1
#define HAVE_SYS_WAIT_H 1
#define HAVE_UNISTD_H 1
#define HAVE_INTTYPES_H 1
#define HAVE_DIRENT_H 1
#define STDC_HEADERS 1
#define POSIX 1

/* System calls / libc functions the sysroot implements. */
#define HAVE_GETCWD 1
#define HAVE_MKSTEMP 1
#define HAVE_FDOPEN 1
#define HAVE_DUP 1
#define HAVE_DUP2 1
#define HAVE_GETTIMEOFDAY 1
#define HAVE_CLOCK_GETTIME 1
#define HAVE_SIGACTION 1
#define HAVE_ATEXIT 1
#define HAVE_ISATTY 1
#define HAVE_REALPATH 1
#define HAVE_STRDUP 1
#define HAVE_STRERROR 1
#define HAVE_STRTOLL 1
#define HAVE_STRCASECMP 1
#define HAVE_STRNCASECMP 1
#define HAVE_STRCOLL 1
#define HAVE_SETVBUF 1
#define HAVE_WAITPID 1
/* main.c:89 derives HAVE_WAIT_NOHANG from HAVE_WAITPID. */
#define HAVE_SA_RESTART 1
/* sysroot string.h has memrchr; its GNU signature matches make's use. */
#define HAVE_MEMRCHR 1
/* HAVE_UMASK is set so makeint.h does NOT typedef mode_t (the sysroot
 * sys/types.h already does, as unsigned int); the sysroot itself provides
 * umask() (src/libc/src/stat.c: records the mask, FAT16 applies nothing),
 * which also means misc.c's value-0 fallback is never selected. */
#define HAVE_UMASK 1

/* Value-guarded fallbacks that make self-provides (keep 0). */
#define HAVE_STPCPY 0       /* misc.c provides stpcpy fallback           */
#define HAVE_DECL_GETLOADAVG 0 /* job.c declares getloadavg; stub links  */
#define HAVE_SYS_LOADAVG_H 0

/* Deliberately UNDEFINED (make guards these with #ifdef/#defined()). */
/* #undef HAVE_STRNDUP */     /* xstrndup uses its malloc+strncpy path   */
/* #undef HAVE_MEMPCPY */     /* glob.c uses its own concatenation       */
/* #undef HAVE_WAIT3 */       /* waitpid path (WAIT_NOHANG via HAVE_WAITPID) */
/* #undef HAVE_SIGSETMASK */  /* bsd_signal falls back to signal()       */
/* #undef HAVE_GETRLIMIT */
/* #undef HAVE_SETRLIMIT */
/* #undef HAVE_SYS_RESOURCE_H */  /* no stack re-sizing (SET_STACK_SIZE) */
/* #undef HAVE_PSELECT */
/* #undef HAVE_SYS_SELECT_H */    /* -j work later; audit S3.3           */
/* #undef HAVE_TTYNAME */         /* makeint.h TTYNAME = "true"          */
/* #undef HAVE_GETPWNAM_R */
/* #undef HAVE_GETLOGIN_R */      /* glob.c uses the non-_r variants     */
/* #undef HAVE_STRUCT_DIRENT_D_TYPE */
#define HAVE_STRSIGNAL 1     /* W2 merge: the sysroot libc provides
                                strsignal() (src/libc/src/string.c); a value
                                of 1 hides makeint.h's own decl and
                                signame.c's fallback definition, so MAKE.BIN
                                links against the real one. */
/* #undef MAKE_JOBSERVER */   /* -j1 v1 (audit S3.3): an UNDEF compiles
                                 the jobserver section OUT of posixos.c/
                                 os.h (a value of 0 would keep it active) */

/* Make feature switches. */
#define ENABLE_NLS 0
#define MAKE_LOAD 0
/* #undef HAVE_GUILE */  /* UNDEF, not 0: guile.c guards its real branch
                            (which pulls <libguile.h>) with #ifdef HAVE_GUILE;
                            undefined means the stub branch compiles */

/* Timestamps: whole-second resolution.  The sysroot struct stat carries
 * no nanosecond member (st_atime/st_mtime/st_ctime are longs), so the
 * hi-res path (ST_MTIM_NSEC) must compile out — FILE_TIMESTAMP_HI_RES 0
 * selects the plain (st_mtime, 0) branch in filedef.h.  The RTC also only
 * reports whole seconds, so nothing is lost. */
#define FILE_TIMESTAMP_HI_RES 0

/* default.c's built-in rules reference the SCCS "get" command token;
 * configure substitutes it (usually "get"). */
#define SCCS_GET "get"

/* remake.c searches LIBDIR for -lfoo library archives (the implicit
 * library search); configure substitutes it from --libdir.  No archives
 * exist on this OS; keep the usual value so the token is defined. */
#define LIBDIR "/lib"

/* Host identification (make --version / $(MAKE_HOST)): match the build
 * arch so -v reports the real target. */
#if defined(__aarch64__)
#define MAKE_HOST "aarch64-hobbyos"
#elif defined(__x86_64__)
#define MAKE_HOST "x86_64-hobbyos"
#else
#define MAKE_HOST "hobbyos"
#endif

/* POSIX says vfork() may share the parent's address space; HobbyOS has no
 * vfork, and fork() is the correct (and safe) substitute here. */
#define vfork fork

/* HobbyOS crt0 ABI: main(argc, argv) only -- no environment pointer in a
 * register (src/libc/crt0.c).  Make's POSIX build would read garbage in
 * its third parameter (crash at the environment-scanning loop, VA ~0xF0).
 * This pins the two-arg main, so make falls back to environ exactly like
 * its own z/OS path (main.c:1164-1172, 1485-1491; marked [HobbyOS port]). */
#define HOBBYOS_NO_ENVP_ARG 1

/* Sysroot declaration shims.  HobbyOS declares these in
 * src/user_include/libc.h, which make's sources never include (they are
 * plain <unistd.h> consumers), and the sysroot <unistd.h> itself omits
 * them; make's own build gets them from glibc's unistd.h.  getlogin() is
 * backed by hb_stubs.c (audit S3.2 row); fork()/pipe() by the libc
 * (fork=libc.c SYS_FORK, pipe=libc.c SYS_PIPE).  POSIX-mandated decls
 * only, matching glibc's signatures. */
int fork(void);
int pipe(int fds[2]);
char *getlogin(void);
